const participants = [...new Set([...game.canvas.tokens.controlledObjects.values()].map(t=>t.actor))].filter(p=>p.type === "pokemon");

if (!participants.length) {
  ui.notifications.error("Please select the participating Pokemon")
  return;
}

const budgetField = new foundry.data.fields.NumberField({
  label: "XP Budget",
  placeholder: 100,
  min: 0
}, {
  name: "budget"
});

const expBudget = await foundry.applications.api.DialogV2.wait({
  window: { title: "XP Budget" },
  content: budgetField.toFormGroup({}).outerHTML,
  buttons: [
    {
      action: "apply",
      label: "Apply",
      callback: (event, button) => {
        const form = button.closest("form");
        const formData = new FormData(form);
        return Number(formData.get("budget"));
      }
    }
  ]
});

if (!expBudget || expBudget < 0) {
  return;
}

const falseCombat = {
  id: foundry.utils.randomID(),
  combatants: participants.map(actor=>({actor})),
  expBudget: expBudget,
  hasEnemyTrainers: false
}

new CONFIG.PTU.ui.combatXPDialog.sheetClass(falseCombat).render(true)
